# Solução

**Ideia central:** O valor máximo após os K feitiços é $V_K(x) = W^K(x)$, onde $W(v)=\max_i(a_i v+b_i)$ (provado por indução via "último feitiço aplicado"). Como $W$ é a envoltória superior de retas (CHT), a órbita pode ser simulada pulando segmentos: todos os cruzamentos são $\le 10^9$ (numerador $\le 10^9$, denominador $\ge 1$), então para $v \ge 10^9+1$ a reta de maior coeficiente domina eternamente → trova final com forma fechada. Cada segmento de coeficiente $a\ge2$ pelo menos dobra $v$, logo $\le \sim 31$ segmentos visitados por pergunta. Refeições: vale usar todas (aumentam estritamente), em ordem crescente de $(a-1)/b$ (independente de $x$), aplicadas após os feitiços. Todas as comparações são exatas (inteiros/racionais via cross-multiplicação), a módulo só entra no valor final.

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
typedef __int128 lll;
static const ll MOD = 1000000007LL;
static const ll THRESH = 1000000001LL; // > any crossing value (crossings <= 1e9)

static ll pw(ll b, ll e){ b%=MOD; if(b<0)b+=MOD; ll r=1; while(e>0){ if(e&1) r=r*b%MOD; b=b*b%MOD; e>>=1; } return r; }

static char ibuf[1 << 23];
static size_t ip_ = 0, il_ = 0;
static inline int gc(){ if(ip_==il_){ il_=fread(ibuf,1,sizeof(ibuf),stdin); ip_=0; if(!il_) return -1; } return (unsigned char)ibuf[ip_++]; }
static inline ll rd(){ int c=gc(); while(c!=-1 && (c<'0'||c>'9')) c=gc(); ll x=0; while(c>='0'&&c<='9'){ x=x*10+(c-'0'); c=gc(); } return x; }

int main(){
    int N = (int)rd(), M = (int)rd(); ll K = rd();
    vector<ll> SA(N), SB(N), MA(M), MB(M);
    for(int i=0;i<N;i++) SA[i]=rd();
    for(int i=0;i<N;i++) SB[i]=rd();
    for(int i=0;i<M;i++) MA[i]=rd();
    for(int i=0;i<M;i++) MB[i]=rd();
    int Q = (int)rd();

    // feitiços: dedup por coeficiente (maior b), envoltória superior (CHT)
    vector<int> sord(N); for(int i=0;i<N;i++) sord[i]=i;
    sort(sord.begin(), sord.end(), [&](int i,int j){ if(SA[i]!=SA[j]) return SA[i]<SA[j]; return SB[i]>SB[j]; });
    vector<ll> sl; sl.reserve(N);
    vector<ll> bt; bt.reserve(N);
    for(int t=0;t<N;t++){
        int i=sord[t];
        if(!sl.empty() && sl.back()==SA[i]) continue; // mesmo coeficiente: mantém maior b
        ll a=SA[i], b=SB[i];
        while(sl.size()>=2){
            size_t sz=sl.size();
            lll numT=(lll)bt[sz-1]-b, denT=(lll)a-sl[sz-1];
            lll numP=(lll)bt[sz-2]-bt[sz-1], denP=(lll)sl[sz-1]-sl[sz-2];
            if(numT*denP <= numP*denT){ sl.pop_back(); bt.pop_back(); } else break;
        }
        sl.push_back(a); bt.push_back(b);
    }
    int L = (int)sl.size();
    vector<ll> crNum(max(0,L-1)), crDen(max(0,L-1));
    for(int i=0;i+1<L;i++){ crNum[i]=bt[i]-bt[i+1]; crDen[i]=sl[i+1]-sl[i]; } // cruzamentos (num/den), estritamente crescentes
    ll aTop = sl.back(), bTopM = bt.back() % MOD;

    // refeições: todas usadas, ordem crescente de (a-1)/b (b=0 vai por último)
    vector<int> mord(M); for(int i=0;i<M;i++) mord[i]=i;
    sort(mord.begin(), mord.end(), [&](int i,int j){
        bool infi=(MB[i]==0), infj=(MB[j]==0);
        if(infi||infj){ if(infi&&infj) return false; return infj; }
        lll l=(lll)(MA[i]-1)*MB[j], r=(lll)(MA[j]-1)*MB[i];
        return l<r;
    });
    ll Am=1, Bm=0;
    for(int t=0;t<M;t++){
        int i=mord[t];
        ll a=MA[i]%MOD, b=MB[i]%MOD;
        Bm=(a*Bm+b)%MOD; Am=a*Am%MOD;
    }
    ll invTopA = pw(aTop-1, MOD-2);

    for(int qn=0; qn<Q; qn++){
        ll x = rd();
        ll Vmod;
        if(aTop == 1){ // todos os feitiços são (1,b): máximo b domina sempre
            Vmod = (x % MOD + (K % MOD) * bTopM) % MOD;
        } else {
            ll v = x, rem = K;
            while(rem > 0){
                if(v >= THRESH) break;               // reta do topo domina para todo v >= 1e9+1
                int lo=0, hi=L-1;                    // acha segmento contendo v
                while(lo<hi){ int mid=(lo+hi)>>1; if((lll)v*crDen[mid]<(lll)crNum[mid]) hi=mid; else lo=mid+1; }
                if(lo == L-1) break;                 // topo: trova final
                ll a=sl[lo], b=bt[lo];
                if(a == 1){                          // aditivo: salto em forma fechada
                    lll diff = (lll)crNum[lo]-(lll)v*crDen[lo];   // > 0
                    lll bd = (lll)b*crDen[lo];
                    lll nst = (diff + bd - 1) / bd;               // aplicações até sair do segmento
                    ll n = (ll)nst; if(n > rem) n = rem;
                    v += n*b; rem -= n;
                } else {                             // misto (a>=2): passos unitários (v dobra, poucos passos)
                    ll cn=crNum[lo], cd=crDen[lo];
                    while(rem > 0 && (lll)v*cd < (lll)cn){
                        v = a*v + b;
                        rem--;
                    }
                }
            }
            if(rem > 0){ // K-usos restantes com a reta do topo (aTop, bTop)
                ll g = pw(aTop, rem);
                ll ssum = (g + MOD - 1) % MOD * invTopA % MOD;
                Vmod = (g * (v % MOD) % MOD + bTopM * ssum) % MOD;
            } else {
                Vmod = v % MOD;
            }
        }
        ll ans = (Am * Vmod + Bm) % MOD;
        printf("%lld\n", ans);
    }
    return 0;
}
```

